if (charter.MemberIds.Any(id => !state.Actors.Any(x => x.Id == id) || !state.Lives.Any(x => x.ActorId == id)
    || !state.Characters.Any(x => x.ActorId == id) || !state.Conditions.Any(x => x.Target == id)))
    return "ExpeditionCloseMemberFactsMissing";

if (state.WorldTraversals.Any(x => members.Contains(x.ActorId))
    || state.RouteTravels.Any(x => members.Contains(x.TravelerId) && x.Status == ExpeditionRouteTravelStatus.Moving))
    return "ExpeditionCloseUnresolvedTraversal";

if (!units.Any(x => x.Id == sale.Basis.GoodsLotId && x.Status == MiningUnitStatus.Extracted && x.ReceivedLotId == sale.Basis.GoodsLotId)
    || !units.Any(x => x.Id == SharedMiningFixture.UnitB && x.Status == MiningUnitStatus.Forfeited)
    || units.Any(x => x.Status == MiningUnitStatus.Available))
    return "ExpeditionCloseMiningDispositionsIncomplete";

if (state.InventoryCombat || PendingCalendarChoice(state) || ManufacturingChoicePending(state)
    || state.Encounter != null && !ResolvedConflict(state))
    return "NextCharterAssentStableBoundaryRequired";

if (!charterAttemptProfile.CurrentFatigueHistoryEstablished || state.WorldSchedule.Origin != authority.Epoch
    || state.RuleClock < authority.Epoch || state.RuleClock >= authority.FatigueUntil)
    return "CharterCurrentFatigueBasisUnavailable";

if (state.InventoryCombat || PendingCalendarChoice(state) || ManufacturingChoicePending(state)
    || state.Encounter != null && !ResolvedConflict(state) || current.TacticalTransition)
    return "CharterTacticalTransitionRequired";

if (attempt.OutboundArrived == null || attempt.ReturnStarted != null
    || !AtSalePosition(state, actor, attempt.Authority.ApproachX, attempt.Authority.ApproachY))
    return "CharterObservationRequiresStationaryArrival";

if (specimen == null || lotId != specimen.LotId || recipe.Id != ManufacturingRules.Recipe4Id
    || recipe.Components[3].Id != ConnectedBloodSpecimen.MaterialId)
    return "BloodSpecimenBindingMismatch";
